<?php $enrollment = $card['enrollment']; $studentName = trim(implode(' ', array_filter([$enrollment->first_name, $enrollment->middle_name, $enrollment->last_name]))); ?>
<section class="card border-0 shadow-sm"><div class="card-body p-4"><div class="text-center border-bottom pb-3 mb-3"><div class="text-secondary small">PRECIOUS LITTLE LIGHTS ACADEMY</div><h1 class="h4 fw-bold mb-1">Student Report Card</h1><div><?= html_escape($enrollment->academic_year); ?></div></div>
<div class="row g-2 mb-4"><div class="col-8"><span class="text-secondary small">Student</span><div class="fw-semibold"><?= html_escape($studentName); ?></div></div><div class="col-4"><span class="text-secondary small">Student no.</span><div class="fw-semibold"><?= html_escape($enrollment->student_no ?: '—'); ?></div></div><div class="col-6"><span class="text-secondary small">Grade</span><div><?= html_escape($grade_label); ?></div></div><div class="col-6"><span class="text-secondary small">Section</span><div><?= html_escape($enrollment->section_name ?: $enrollment->section ?: 'Not assigned'); ?></div></div></div>
<h2 class="h6 fw-bold">Academic results</h2><div class="table-responsive"><table class="table table-bordered align-middle"><thead class="table-light"><tr><th>Subject</th><th>Prelim</th><th>Midterm</th><th>Finals</th><th>Final grade</th><th>Review</th></tr></thead><tbody><?php if (!$card['grades']): ?><tr><td colspan="6" class="text-center text-secondary">No subject offerings for this grade and year.</td></tr><?php else: foreach ($card['grades'] as $grade): $gradeFields = ['prelim_grade', 'midterm_grade', 'finals_grade', 'final_grade']; $completeApprovedGrade = $grade->review_status === 'approved'; foreach ($gradeFields as $field) if ($grade->{$field} === null) $completeApprovedGrade = false; ?><tr><td><?= html_escape($grade->subject_name); ?><?php if ($grade->subject_code): ?><div class="small text-secondary"><?= html_escape($grade->subject_code); ?></div><?php endif; ?></td><?php foreach ($gradeFields as $field): ?><td><?= $completeApprovedGrade ? html_escape(number_format((float) $grade->{$field}, 2)) : '—'; ?></td><?php endforeach; ?><td><?php if (!$grade->review_status): ?><span class="badge text-bg-secondary">Not entered</span><?php elseif ($completeApprovedGrade): ?><span class="badge text-bg-success">Approved</span><?php elseif ($grade->review_status === 'approved'): ?><span class="badge text-bg-warning">Incomplete</span><?php elseif ($grade->review_status === 'returned'): ?><span class="badge text-bg-warning">Returned</span><?php else: ?><span class="badge text-bg-info">Pending review</span><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
<h2 class="h6 fw-bold mt-4">Attendance by subject</h2><div class="table-responsive"><table class="table table-bordered align-middle"><thead class="table-light"><tr><th>Subject</th><th>Present</th><th>Absent</th><th>Late</th><th>Excused</th></tr></thead><tbody><?php $attendanceTotal = 0; foreach ($card['grades'] as $grade): $counts = $card['attendance'][$grade->subject_name] ?? []; $attendanceTotal += array_sum($counts); ?><tr><td><?= html_escape($grade->subject_name); ?></td><?php foreach (['present', 'absent', 'late', 'excused'] as $status): ?><td><?= (int) ($counts[$status] ?? 0); ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if (!$card['grades']): ?><tr><td colspan="5" class="text-center text-secondary">No subject attendance records.</td></tr><?php endif; ?></tbody><tfoot class="table-light"><tr><th>Total recorded meetings</th><th colspan="4"><?= (int) $attendanceTotal; ?></th></tr></tfoot></table></div><div class="small text-secondary mt-3">Only complete, approved grade sets are shown. Pending, returned, or incomplete grades are excluded from results.</div></div></section>
